/* Matches the language subtag, case-insensitively: "zh" with anything after it is zh-Hans. */
static int is_language(const char *tag, const char *language) {
    size_t i = 0;
    for (; language[i]; i++) {
        if (tolower((unsigned char)tag[i]) != language[i]) return 0;
    }
    return tag[i] == '\0' || tag[i] == '-' || tag[i] == '_';
}

yk_locale_t yk_locale_from_tag(const char *tag) {
    if (!tag) return YK_LOCALE_EN;
    if (is_language(tag, "zh")) return YK_LOCALE_ZH_HANS;
    if (is_language(tag, "ja")) return YK_LOCALE_JA;
    if (is_language(tag, "es")) return YK_LOCALE_ES_419;
    return YK_LOCALE_EN;
}

const char *yk_str(yk_locale_t locale, yk_str_t id) {
    if ((unsigned)locale >= YK_LOCALE_COUNT) locale = YK_LOCALE_EN;
    if ((unsigned)id >= YK_STR_COUNT) return "";
    return TABLE[locale][id];
}
